from playwright.sync_api import sync_playwright
from pathlib import Path
import subprocess,sys,time,os,json
root=Path(__file__).resolve().parents[1];out=root/'Documentation/evidence';out.mkdir(exist_ok=True)
video=root/'Video';env=os.environ.copy();env.update({'HLD_MODE':'local','HF_HUB_OFFLINE':'1','HF_HUB_DISABLE_TELEMETRY':'1'})
server=subprocess.Popen([sys.executable,'-m','streamlit','run',str(root/'Code/app.py'),'--server.port=8522','--server.address=127.0.0.1','--browser.gatherUsageStats=false'],env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
