  page.get_by_role('tab',name='Cited Q&A',exact=True).click()
  for exp in page.locator('[data-testid="stExpander"]:visible').all():
   try:exp.locator('summary').click()
   except Exception:pass
  scene('GROUNDING: expand retrieval evidence and read the exact source text. Similarity is not a correctness probability, and a valid citation ID is not proof of entailment.',25)
  page.get_by_role('tab',name='Architecture inventory',exact=True).click()
  scene('STRUCTURED EXTRACTION: deterministic parsing produces components, signals, interfaces and dependencies with section citations. Exportable JSON preserves traceability.',25)
