  page.get_by_role('tab',name='Cited Q&A',exact=True).click()
  combos=page.get_by_role('combobox');combos.nth(2).click();page.get_by_role('option',name='1.0',exact=True).click();time.sleep(2)
  question('What was the PedalPosition timeout in revision 1.0?')
  scene('HISTORICAL SEARCH: selecting revision 1.0 retrieves historical evidence rather than silently mixing old and current sources. The recorded answer must still be reviewed.',25)
  combos=page.get_by_role('combobox');combos.nth(1).click();page.get_by_role('option',name='thermal',exact=True).click();time.sleep(2)
  page.get_by_role('tab',name='Architecture inventory',exact=True).click()
